#!/usr/bin/env bash
# Parts of mobile-site/ are generated by scripts/site/render_site.py: the
# privacy page body (from PRIVACY.md), the site directory (from
# scripts/site/sites.json), each page's canonical/hreflang lines, every page
# under mobile-site/zh/, and sitemap.xml. Fails when any committed file
# differs from what the script would write.
#
# Usage: scripts/ci/check-site.sh
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$repo_root"

if ! python3 scripts/site/render_site.py --check; then
  echo "::error::Generated files in mobile-site/ are out of date. Run scripts/site/render_site.py and commit."
  exit 1
fi
